solutions.naive:
class Solution:
    def distinctEchoSubstrings(self, text: str) -> int:
        found = set()
        n = len(text)
        for start in range(n):
            for length in range(2, n - start + 1, 2):
                half = length // 2
                sub = text[start:start + length]
                if sub[:half] == sub[half:]:
                    found.add(sub)
        return len(found)

